// Prescription search over the Egyptian drug list (drug-data.ts, generated by scripts/build-drug-catalogue.mjs).
// Pure and in memory: no I/O, so a unit spec can call it directly.

import { normaliseArabicName } from "../patients/domain/normalise-arabic.ts";
import { DRUG_ROWS } from "./drug-data.ts";

export interface DrugHit {
  /** The English commercial name: what goes into the prescription's text field. */
  name: string;
  arabic: string;
  scientific: string | null;
}

interface Entry extends DrugHit {
  nameKey: string;
  arabicKey: string;
  scientificKey: string;
  /** The Arabic name without its long vowels: the list's Arabic is a phonetic alias, so spellings drift. */
  arabicSkeleton: string;
}

const fold = (text: string): string => normaliseArabicName(text).toLowerCase().replace(/\s+/g, " ").trim();

const skeleton = (text: string): string => text.replace(/[اويى]/gu, "");

let entries: Entry[] | null = null;

function load(): Entry[] {
  entries ??= DRUG_ROWS.map((row) => {
    const [name = "", arabic = "", scientific = ""] = row.split("|");
    return {
      name,
      arabic,
      scientific: scientific === "" ? null : scientific,
      nameKey: fold(name),
      arabicKey: fold(arabic),
      scientificKey: fold(scientific),
      arabicSkeleton: skeleton(fold(arabic)),
    };
  });
  return entries;
}

/** Lower is better: a name that starts with the query beats one that merely contains it. */
function rank(entry: Entry, tokens: string[]): number | null {
  let worst = 0;
  for (const token of tokens) {
    let best: number | null = null;
    for (const [key, base] of [[entry.nameKey, 0], [entry.arabicKey, 0], [entry.scientificKey, 3]] as const) {
      const at = key.indexOf(token);
      if (at === -1) continue;
      const score = base + (at === 0 ? 0 : key[at - 1] === " " ? 1 : 2);
      if (best === null || score < best) best = score;
    }
    const bare = skeleton(token);
    if (bare !== "" && bare !== token) {
      const at = entry.arabicSkeleton.indexOf(bare);
      // A fallback: ranked below an exact spelling that starts or begins a word.
      const fallback = at === 0 ? 2 : 3;
      if (at !== -1 && (best === null || fallback < best)) best = fallback;
    }
    if (best === null) return null;
    worst = Math.max(worst, best);
  }
  return worst;
}

/** Matches the English or Arabic commercial name, or the scientific name. Every word must match. */
export function searchDrugs(query: string, limit = 12): DrugHit[] {
  const tokens = fold(query).split(" ").filter((token) => token !== "");
  if (tokens.length === 0) return [];

  const hits: { entry: Entry; score: number }[] = [];
  for (const entry of load()) {
    const score = rank(entry, tokens);
    if (score !== null) hits.push({ entry, score });
  }
  hits.sort((a, b) => a.score - b.score || a.entry.name.length - b.entry.name.length);
  return hits.slice(0, limit).map(({ entry }) => ({ name: entry.name, arabic: entry.arabic, scientific: entry.scientific }));
}
